package com.airplaytv.core.fairplay

import java.util.zip.CRC32

/**
 * Fixed lookup tables used by [Playfair].
 *
 * The tables are extracted from the reference implementation into a single
 * binary blob (generated by `tools/fairplay_gen.py`), because inlining them as
 * Kotlin literals would produce oversized classes and method bodies (the JVM
 * limits a method to 64 KiB of bytecode and APKs should not carry hundreds of
 * kilobytes of hex literals).
 *
 * At runtime a `/fairplay/tables.bin` classpath resource is preferred when
 * present; otherwise the generated [FairPlayTableData] blob is decoded. This
 * project's Gradle build registers `src/main/resources` twice (so any resource
 * file is reported as a duplicate), hence the embedded fallback.
 *
 * Blob layout (all integers little-endian):
 * ```
 * 0  4  magic "FPTB"
 * 4  4  format version (1)
 * 8  4  payload length in bytes
 * 12 4  CRC-32 (zlib) of the payload
 * 16 .. payload: table_s1, table_s2, table_s3, table_s4,
 *       table_s5..s8 (u32), table_s9 (u32), table_s10,
 *       message_key (4x144), message_iv (4x16),
 *       z_key, x_key, t_key, indexMangle,
 *       static_source_1, static_source_2, initial_session_key, default_sap
 * ```
 * The generator is `tools/fairplay_gen.py`.
 */
internal object FairPlayTables {

    const val EXPECTED_SIZE = 101_423

    private const val HEADER_SIZE = 16
    private const val VERSION = 1

    private const val S1_SIZE = 10_240
    private const val S2_SIZE = 36_864
    private const val S3_SIZE = 4_096
    private const val S4_SIZE = 36_864
    private const val S5_SIZE = 256 * 4
    private const val S6_SIZE = 256 * 4
    private const val S7_SIZE = 256 * 4
    private const val S8_SIZE = 256 * 4
    private const val S9_SIZE = 1_024 * 4
    private const val S10_SIZE = 4_096
    private const val MESSAGE_KEY_SIZE = 4 * 144
    private const val MESSAGE_IV_SIZE = 4 * 16
    private const val Z_KEY_SIZE = 16
    private const val X_KEY_SIZE = 16
    private const val T_KEY_SIZE = 16
    private const val INDEX_MANGLE_SIZE = 11
    private const val STATIC_SOURCE_1_SIZE = 17
    private const val STATIC_SOURCE_2_SIZE = 47
    private const val INITIAL_SESSION_KEY_SIZE = 16
    private const val DEFAULT_SAP_SIZE = 276

    private const val S1_OFF = HEADER_SIZE
    private const val S2_OFF = S1_OFF + S1_SIZE
    private const val S3_OFF = S2_OFF + S2_SIZE
    private const val S4_OFF = S3_OFF + S3_SIZE
    private const val S5_OFF = S4_OFF + S4_SIZE
    private const val S6_OFF = S5_OFF + S5_SIZE
    private const val S7_OFF = S6_OFF + S6_SIZE
    private const val S8_OFF = S7_OFF + S7_SIZE
    private const val S9_OFF = S8_OFF + S8_SIZE
    private const val S10_OFF = S9_OFF + S9_SIZE
    private const val MESSAGE_KEY_OFF = S10_OFF + S10_SIZE
    private const val MESSAGE_IV_OFF = MESSAGE_KEY_OFF + MESSAGE_KEY_SIZE
    private const val Z_KEY_OFF = MESSAGE_IV_OFF + MESSAGE_IV_SIZE
    private const val X_KEY_OFF = Z_KEY_OFF + Z_KEY_SIZE
    private const val T_KEY_OFF = X_KEY_OFF + X_KEY_SIZE
    private const val INDEX_MANGLE_OFF = T_KEY_OFF + T_KEY_SIZE
    private const val STATIC_SOURCE_1_OFF = INDEX_MANGLE_OFF + INDEX_MANGLE_SIZE
    private const val STATIC_SOURCE_2_OFF = STATIC_SOURCE_1_OFF + STATIC_SOURCE_1_SIZE
    private const val INITIAL_SESSION_KEY_OFF = STATIC_SOURCE_2_OFF + STATIC_SOURCE_2_SIZE
    private const val DEFAULT_SAP_OFF = INITIAL_SESSION_KEY_OFF + INITIAL_SESSION_KEY_SIZE
    private const val PAYLOAD_END = DEFAULT_SAP_OFF + DEFAULT_SAP_SIZE

    private class Data(
        val s1: ByteArray,
        val s2: ByteArray,
        val s3: ByteArray,
        val s4: ByteArray,
        val s5: IntArray,
        val s6: IntArray,
        val s7: IntArray,
        val s8: IntArray,
        val s9: IntArray,
        val s10: ByteArray,
        val messageKey: ByteArray,
        val messageIv: ByteArray,
        val zKey: ByteArray,
        val xKey: ByteArray,
        val tKey: ByteArray,
        val indexMangle: ByteArray,
        val staticSource1: ByteArray,
        val staticSource2: ByteArray,
        val initialSessionKey: ByteArray,
        val defaultSap: ByteArray,
    )

    private val data: Data by lazy(LazyThreadSafetyMode.SYNCHRONIZED) { load() }

    fun s1(index: Int): Int = data.s1[index].toInt() and 0xff
    fun s2(index: Int): Int = data.s2[index].toInt() and 0xff
    fun s3(index: Int): Int = data.s3[index].toInt() and 0xff
    fun s4(index: Int): Int = data.s4[index].toInt() and 0xff
    fun s5(index: Int): Int = data.s5[index]
    fun s6(index: Int): Int = data.s6[index]
    fun s7(index: Int): Int = data.s7[index]
    fun s8(index: Int): Int = data.s8[index]
    fun s9(index: Int): Int = data.s9[index]
    fun s10(index: Int): Int = data.s10[index].toInt() and 0xff

    fun messageKey(mode: Int, index: Int): Int = data.messageKey[mode * 144 + index].toInt() and 0xff
    fun messageIv(mode: Int, index: Int): Int = data.messageIv[mode * 16 + index].toInt() and 0xff
    fun zKey(index: Int): Int = data.zKey[index].toInt() and 0xff
    fun xKey(index: Int): Int = data.xKey[index].toInt() and 0xff
    fun tKey(index: Int): Int = data.tKey[index].toInt() and 0xff
    fun indexMangle(index: Int): Int = data.indexMangle[index].toInt() and 0xff
    fun staticSource1(index: Int): Int = data.staticSource1[index].toInt() and 0xff
    fun staticSource2(index: Int): Int = data.staticSource2[index].toInt() and 0xff
    fun initialSessionKey(index: Int): Int = data.initialSessionKey[index].toInt() and 0xff
    fun defaultSap(index: Int): Int = data.defaultSap[index].toInt() and 0xff

    fun defaultSap(): ByteArray = data.defaultSap.copyOf()

    private fun load(): Data {
        // Prefer a binary resource if the build ever ships one, otherwise use
        // the generated, compile-time embedded blob (see tools/fairplay_gen.py).
        val raw = FairPlayTables::class.java.getResourceAsStream("/fairplay/tables.bin")
            ?.use { it.readBytes() }
            ?: FairPlayTableData.decode()
        check(raw.size == EXPECTED_SIZE) {
            "FairPlay table asset has ${raw.size} bytes, expected $EXPECTED_SIZE; " +
                "the resource is truncated or corrupt, regenerate it with tools/fairplay_gen.py"
        }
        check(raw[0] == 'F'.code.toByte() && raw[1] == 'P'.code.toByte() &&
            raw[2] == 'T'.code.toByte() && raw[3] == 'B'.code.toByte()) {
            "FairPlay table asset has a bad magic header"
        }
        val version = le32(raw, 4)
        check(version == VERSION) { "FairPlay table asset version $version, expected $VERSION" }
        val payloadLength = le32(raw, 8)
        check(payloadLength == PAYLOAD_END - HEADER_SIZE) {
            "FairPlay table asset declares payload length $payloadLength, expected ${PAYLOAD_END - HEADER_SIZE}"
        }
        val expectedCrc = le32(raw, 12).toLong() and 0xffffffffL
        val crc = CRC32()
        crc.update(raw, HEADER_SIZE, raw.size - HEADER_SIZE)
        check(crc.value == expectedCrc) {
            "FairPlay table asset CRC mismatch (got ${crc.value}, expected $expectedCrc)"
        }
        return Data(
            s1 = raw.copyOfRange(S1_OFF, S1_OFF + S1_SIZE),
            s2 = raw.copyOfRange(S2_OFF, S2_OFF + S2_SIZE),
            s3 = raw.copyOfRange(S3_OFF, S3_OFF + S3_SIZE),
            s4 = raw.copyOfRange(S4_OFF, S4_OFF + S4_SIZE),
            s5 = u32Array(raw, S5_OFF, S5_SIZE / 4),
            s6 = u32Array(raw, S6_OFF, S6_SIZE / 4),
            s7 = u32Array(raw, S7_OFF, S7_SIZE / 4),
            s8 = u32Array(raw, S8_OFF, S8_SIZE / 4),
            s9 = u32Array(raw, S9_OFF, S9_SIZE / 4),
            s10 = raw.copyOfRange(S10_OFF, S10_OFF + S10_SIZE),
            messageKey = raw.copyOfRange(MESSAGE_KEY_OFF, MESSAGE_KEY_OFF + MESSAGE_KEY_SIZE),
            messageIv = raw.copyOfRange(MESSAGE_IV_OFF, MESSAGE_IV_OFF + MESSAGE_IV_SIZE),
            zKey = raw.copyOfRange(Z_KEY_OFF, Z_KEY_OFF + Z_KEY_SIZE),
            xKey = raw.copyOfRange(X_KEY_OFF, X_KEY_OFF + X_KEY_SIZE),
            tKey = raw.copyOfRange(T_KEY_OFF, T_KEY_OFF + T_KEY_SIZE),
            indexMangle = raw.copyOfRange(INDEX_MANGLE_OFF, INDEX_MANGLE_OFF + INDEX_MANGLE_SIZE),
            staticSource1 = raw.copyOfRange(STATIC_SOURCE_1_OFF, STATIC_SOURCE_1_OFF + STATIC_SOURCE_1_SIZE),
            staticSource2 = raw.copyOfRange(STATIC_SOURCE_2_OFF, STATIC_SOURCE_2_OFF + STATIC_SOURCE_2_SIZE),
            initialSessionKey = raw.copyOfRange(
                INITIAL_SESSION_KEY_OFF, INITIAL_SESSION_KEY_OFF + INITIAL_SESSION_KEY_SIZE
            ),
            defaultSap = raw.copyOfRange(DEFAULT_SAP_OFF, DEFAULT_SAP_OFF + DEFAULT_SAP_SIZE),
        )
    }

    private fun le32(bytes: ByteArray, offset: Int): Int =
        (bytes[offset].toInt() and 0xff) or
            ((bytes[offset + 1].toInt() and 0xff) shl 8) or
            ((bytes[offset + 2].toInt() and 0xff) shl 16) or
            ((bytes[offset + 3].toInt() and 0xff) shl 24)

    private fun u32Array(bytes: ByteArray, offset: Int, count: Int): IntArray =
        IntArray(count) { le32(bytes, offset + it * 4) }
}
